def solve(n, edges, start):
    from collections import deque
    graph=[[] for _ in range(n)]
    for u,v in edges: graph[u].append(v); graph[v].append(u)
    distance=[-1]*n; distance[start]=0; queue=deque([start])
    while queue:
        u=queue.popleft()
        for v in graph[u]:
            if distance[v]<0: distance[v]=distance[u]+1; queue.append(v)
    return distance
